<?php
class AuthController {
 public function loginForm():void{View::render('auth/login');}
 public function registerForm():void{View::render('auth/register');}
 public function login():void{verify_csrf();$now=time();$_SESSION['_login_attempts']=array_values(array_filter($_SESSION['_login_attempts']??[],fn($t)=>$t>$now-900));if(count($_SESSION['_login_attempts'])>=8){http_response_code(429);exit('Trop de tentatives. Réessayez dans 15 minutes.');}$u=db_one('SELECT u.*,c.name company_name FROM users u LEFT JOIN companies c ON c.id=u.company_id WHERE u.email=? AND u.status="active"',[trim($_POST['email']??'')]);if(!$u||!password_verify($_POST['password']??'', $u['password'])){$_SESSION['_login_attempts'][]=$now;flash('error','Identifiants incorrects.');redirect('/login');}unset($_SESSION['_login_attempts']);unset($u['password']);Auth::login($u);redirect('/dashboard');}
 public function register():void{verify_csrf();$name=trim($_POST['company']??'');$owner=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!$name||!$owner||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12){flash('error','Vérifiez les champs. Mot de passe : 12 caractères minimum.');redirect('/register');}if(db_one('SELECT id FROM users WHERE email=?',[$email])){flash('error','Cette adresse e-mail existe déjà.');redirect('/register');}$pdo=Database::p();$pdo->beginTransaction();try{$cid=db_exec('INSERT INTO companies(name,sector,created_at) VALUES(?,?,NOW())',[$name,trim($_POST['sector']??'Autre')]);$uid=db_exec('INSERT INTO users(company_id,name,email,password,role,status,created_at) VALUES(?,?,?,?,"owner","active",NOW())',[$cid,$owner,$email,password_hash($pass,PASSWORD_DEFAULT)]);$planId=(int)(db_one('SELECT id FROM plans WHERE code="starter" LIMIT 1')['id']??0);if($planId){db_exec('INSERT INTO subscriptions(company_id,plan_id,status,billing_cycle,starts_at,ends_at,created_at) VALUES(?,?,"trial","monthly",NOW(),DATE_ADD(NOW(),INTERVAL 14 DAY),NOW())',[$cid,$planId]);}$pdo->commit();$newUser=db_one('SELECT u.*,c.name company_name FROM users u JOIN companies c ON c.id=u.company_id WHERE u.id=?',[$uid]);unset($newUser['password']);Auth::login($newUser);redirect('/dashboard');}catch(Throwable $e){$pdo->rollBack();error_log('FasoBusiness registration: '.$e->getMessage());flash('error','Inscription impossible. Vérifiez la configuration et réessayez.');redirect('/register');}}
 public function logout():void{verify_csrf();Auth::logout();redirect('/login');}
}
